python3 -c "
from openpyxl import load_workbook
wb = load_workbook('budget.xlsx')  # data_only=False to see formulas
for ws in wb.worksheets:
    print('Sheet:', ws.title, 'dims:', ws.dimensions, 'max_row:', ws.max_row, 'max_col:', ws.max_column)
    for row in ws.iter_rows():
        for c in row:
            if c.value is not None:
                print(c.coordinate, repr(c.value), '| font color:', c.font.color.rgb if c.font and c.font.color else None)
"

