import os, shutil
print('which soffice:', shutil.which('soffice'))
print('which libreoffice:', shutil.which('libreoffice'))
for base in ['/usr/bin','/usr/local/bin','/opt','/snap/bin']:
    if os.path.isdir(base):
        for f in os.listdir(base):
            if 'office' in f.lower() or 'soffice' in f.lower():
                print(os.path.join(base,f))
